import re, subprocess

def body(path):
    out = subprocess.run(['objdump','-d',path],capture_output=True,text=True).stdout
    lines = []
    for line in out.splitlines():
        m = re.match(r'^\s+([0-9a-f]+):\s+([0-9a-f ]+)\t(.*)$', line)
